cd /tmp/opencode && node -e '
const fs=require("fs");
const b=JSON.parse(fs.readFileSync("boundary.json"))[0].geo_shape.geometry;
const sensors=JSON.parse(fs.readFileSync("sensors.json"));
const R=6371000, rad=Math.PI/180;
function m(lat,lon){ // local metres
  const lat0=-37.81; return [(lon-144.95)*rad*R*Math.cos(lat0*rad), (lat-lat0)*rad*R];
}
// rings
const rings=b.coordinates[0];
function pip(pt,ring){let c=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];if(((yi>pt[0])!=(yj>pt[0]))&&(pt[1]<(xj-xi)*(pt[0]-yi)/(yj-yi)+xi))c=!c;}return c;}
function inPoly(lat,lon){let inside=false;for(const r of rings){if(pip([lat,lon],r))inside=!inside;}return inside;}
// area
let area=0;
for(const r of rings){
  let s=0;
  for(let i=0;i<r.length-1;i++){s+=(r[i][1]*r[i+1][0]-r[i+1][1]*r[i][0]);}
  area+=Math.abs(s/2)*(rad*R)*(rad*R*Math.cos(-37.81*rad))/2?0:0;
}
// proper area via shoelace in metres
function ringArea(r){let s=0;for(let i=0;i<r.length;i++){const a=m(r[i][1],r[i][0]),c=m(r[(i+1)%r.length][1],r[(i+1)%r.length][0]);s+=a[0]*c[1]-c[0]*a[1];}return Math.abs(s/2);}
let totalA=0; rings.forEach((r,i)=>{const a=ringArea(r); totalA += i===0?a:-a;});
console.log("boundary km2", (totalA/1e6).toFixed(2));
// sensors
const outdoor=sensors.filter(s=>s.location_type==="Outdoor");
console.log("outdoor",outdoor.length,"indoor",sensors.length-outdoor.length);
// dedupe
const uniq=[]; for(const s of sensors){const p=m(s.latitude,s.longitude); if(!uniq.some(u=>Math.hypot(u[0]-p[0],u[1]-p[1])<15)){uniq.push(p);}}
console.log("distinct locations within 15m:",uniq.length);
// grid sample
const bb={minLat:-37.85,maxLat:-37.775,minLon:144.92,maxLon:144.995};
const step=0.0004; // ~44m
let cells=0, inside=0;
const dists=[];
for(let lat=bb.minLat;lat<bb.maxLat;lat+=step)for(let lon=bb.minLon;lon<bb.maxLon;lon+=step){
  cells++;
  if(!inPoly(lat,lon))continue; inside++;
  const p=m(lat,lon);
  let dmin=1e9; for(const u of uniq){const d=Math.hypot(u[0]-p[0],u[1]-p[1]); if(d<dmin)dmin=d;}
  dists.push(dmin);
}
console.log("grid cells in boundary (~44m):",inside,"of",cells);
for(const t of [100,150,200,250,300,400,600])console.log("within",t,"m:",(100*dists.filter(d=>d<=t).length/dists.length).toFixed(1)+"%");
dists.sort((a,b)=>a-b);
console.log("median dist",dists[Math.floor(dists.length/2)].toFixed(0),"p90",dists[Math.floor(dists.length*0.9)].toFixed(0),"max",dists[dists.length-1].toFixed(0));
'

