const km2=37.64;
for(const cell of [50,75,100]){
 for(const frac of [1,0.212]){
  const cells=Math.round(km2*1e6/(cell*cell)*frac);
  const vals=cells*168;
  const jsonBytes=vals*7; // "2654.3,"
  console.log(`cell ${cell}m, coverage ${(frac*100).toFixed(0)}%: ${cells} cells, ${vals} values, raw JSON ~${(jsonBytes/1e6).toFixed(1)} MB, gzip ~${(jsonBytes/1e6/7).toFixed(2)} MB`);
 }
}
console.log("sensor-series only: 134*168 =", 134*168, "values ~", (134*168*6/1024).toFixed(0), "KB");
// scoring volume
console.log("score combos: 40 screens x 168 hours =", 40*168);
'

